29: async function request(path, options, fetchImpl) {
30:   let response;
31:   try {
32:     response = await fetchImpl(`${API}${path}`, { ...options, signal: AbortSignal.timeout(120_000) });
33:   } catch (error) {
34:     throw new Error(`OpenRouter unavailable (${error.cause?.code ?? error.name}). No retry was made.`);
35:   }
36:   if (!response.ok) throw new Error(`OpenRouter HTTP ${response.status}. No retry was made.`);
37:   return response.json();
38: }
