40: export async function plan(objective, directory, {
41:   apiKey = process.env.OPENROUTER_API_KEY,
42:   fetchImpl = fetch,
43: } = {}) {
44:   if (typeof objective !== 'string' || !objective.trim()) throw new Error('An objective is required.');
45:   if (!apiKey) throw new Error('Set OPENROUTER_API_KEY before planning.');
46:   const investigate = await repositoryTools(directory);
47:   const output = join(directory, '.tag');
48:   try {
49:     await mkdir(output, { mode: 0o700 });
50:   } catch (error) {
51:     if (error.code === 'EEXIST') throw new Error('.tag already exists. Preserve or move it before starting another experiment.');
52:     throw error;
53:   }
54:   await writeFile(join(output, '.gitignore'), '*\n', { flag: 'wx', mode: 0o600 });
55:   // A failed run is an experimental result: keep what it did and what it answered.
56:   const attempt = { model: MODEL, createdAt: new Date().toISOString(), requests: 0, costUsd: 0, investigation: [] };
57:   let keep = false;
58:   try {
59:     const { data } = await request('/models', {}, fetchImpl);
60:     const model = data?.find(item => item.id === MODEL);
61:     const promptPrice = Number(model?.pricing?.prompt);
62:     const completionPrice = Number(model?.pricing?.completion);
63:     // Deliberately conservative caps, not a general-purpose cost reservation system.
64:     if (!model || !Number.isFinite(promptPrice) || promptPrice < 0 || promptPrice > 0.5 / 1e6
65:       || !Number.isFinite(completionPrice) || completionPrice < 0 || completionPrice > 1.5 / 1e6
66:       || Number(model.pricing.request ?? 0) !== 0) {
67:       throw new Error('Model unavailable or pricing exceeds the seed’s budget caps. Human review required.');
68:     }
69:     const messages = [
70:       { role: 'system', content: instructions },
71:       { role: 'user', content: objective },
72:     ];
73:     const investigation = attempt.investigation;
74:     for (let turn = 1; turn <= MAX_REQUESTS; turn++) {
75:       attempt.requests = turn;
76:       const body = {
77:         model: MODEL, messages, tools, max_tokens: MAX_OUTPUT,
78:         tool_choice: turn === MAX_REQUESTS ? 'none' : 'auto',
79:         temperature: 0.2,
80:         provider: { max_price: { prompt: 0.5, completion: 1.5 } },
81:       };
82:       if (Buffer.byteLength(JSON.stringify(body)) > MAX_CONTEXT_BYTES) {
83:         throw new Error('Research context limit reached. No graph saved; human review required.');
84:       }
85:       const response = await request('/chat/completions', {
86:         method: 'POST',
87:         headers: { Authorization: 'Bearer ' + apiKey, 'Content-Type': 'application/json' },
88:         body: JSON.stringify(body),
89:       }, fetchImpl);
90:       const cost = response.usage?.cost;
91:       attempt.costUsd = attempt.costUsd !== null && typeof cost === 'number' && Number.isFinite(cost) && cost >= 0
92:         ? attempt.costUsd + cost : null;
93:       const choice = response.choices?.[0];
94:       const message = choice?.message;
95:       if (!message || choice.finish_reason === 'length' || response.error) {
96:         throw new Error('The model returned an error or incomplete answer. No retry was made.');
97:       }
98:       if (message.tool_calls?.length) {
99:         if (turn === MAX_REQUESTS || message.tool_calls.length > 12) throw new Error('Investigation limit reached.');
100:         messages.push({ role: 'assistant', content: message.content ?? null, tool_calls: message.tool_calls });
101:         for (const call of message.tool_calls) {
102:           let args;
103:           let result;
104:           try {
105:             args = JSON.parse(call.function.arguments);
106:             result = await investigate(call.function.name, args);
107:           } catch {
108:             // Do not return raw filesystem errors or other environment details to the model.
109:             result = 'Tool unavailable or invalid arguments. Use listed tracked text files and the documented tool parameters.';
110:           }
111:           investigation.push({ tool: call.function.name, arguments: args ?? {}, result });
112:           messages.push({ role: 'tool', tool_call_id: call.id, content: result });
113:         }
114:         continue;
115:       }
116:       if (!investigation.some(item => item.tool === 'read_file' && /^\d+: /.test(item.result))) {
117:         throw new Error('The model proposed a graph without reading repository evidence.');
118:       }
119:       attempt.answer = message.content;
120:       let graph;
121:       try {
122:         graph = validateGraph(JSON.parse(message.content), objective);
123:       } catch (error) {
124:         throw new Error(`Invalid planner graph: ${error.message}. No repair or retry was made.`);
125:       }
126:       graph.run = { model: MODEL, createdAt: attempt.createdAt, requests: turn, costUsd: attempt.costUsd, investigation };
127:       const html = renderGraph(graph);
128:       keep = true;
129:       await writeFile(join(output, 'graph.json'), JSON.stringify(graph, null, 2) + '\n', { flag: 'wx', mode: 0o600 });
130:       await writeFile(join(output, 'graph.html'), html, { flag: 'wx', mode: 0o600 });
131:       return join(output, 'graph.html');
132:     }
133:     throw new Error('Investigation limit reached. No graph saved.');
134:   } catch (error) {
135:     if (!attempt.investigation.length && attempt.answer === undefined) throw error;
136:     // Without this the run's transcript and rejected answer are lost and the failure cannot be diagnosed.
137:     const record = { objective, failure: error.message, run: attempt };
138:     try {
139:       await writeFile(join(output, 'failed-run.json'), JSON.stringify(record, null, 2) + '\n', { flag: 'wx', mode: 0o600 });
140:       keep = true;
141:       throw new Error(`${error.message} The attempt is preserved in .tag/failed-run.json; inspect and move it aside before running again.`);
142:     } catch (writeError) {
143:       throw writeError.message.includes(error.message) ? writeError : error;
144:     }
145:   } finally {
146:     if (!keep) await rm(output, { recursive: true });
147:   }
148: }
