36: export async function repositoryTools(directory) {
37:   const root = await realpath(directory);
38:   const git = async args => (await exec('git', [
39:     '--no-pager', '-c', 'core.fsmonitor=false', '-c', 'log.showSignature=false', '-C', root, ...args,
40:   ], { maxBuffer: 2 * 1024 * 1024, timeout: 10_000 })).stdout;
41:   if ((await git(['rev-parse', '--show-toplevel'])).trim() !== root) {
42:     throw new Error('Choose the repository root directory.');
43:   }
44:   const files = [...new Set((await git(['ls-files', '-z'])).split('\0').filter(path => path && allowed(path)))].sort();
45:   const known = new Set(files);
46:   async function textFile(path) {
47:     if (!known.has(path)) throw new Error('Choose a listed tracked file.');
48:     const absolute = resolve(root, path);
49:     if (await realpath(absolute) !== absolute) throw new Error('Symlinks are not readable.');
50:     const handle = await open(absolute, 'r');
51:     try {
52:       const stat = await handle.stat();
53:       if (!stat.isFile() || stat.size > 256 * 1024) throw new Error('Only text files up to 256 KiB are readable.');
54:       const text = await handle.readFile('utf8');
55:       if (text.includes('\0')) throw new Error('Binary files are not readable.');
56:       return text.split('\n');
57:     } finally {
58:       await handle.close();
59:     }
60:   }
61:   return async function investigate(name, args) {
62:     if (!args || typeof args !== 'object' || Array.isArray(args)) throw new Error('Expected an argument object.');
63:     switch (name) {
64:       case 'list_files': {
65:         const offset = args.offset ?? 0;
66:         if (!Number.isInteger(offset) || offset < 0) throw new Error('Invalid offset.');
67:         return JSON.stringify({ files: files.slice(offset, offset + 100), total: files.length, nextOffset: offset + 100 < files.length ? offset + 100 : null });
68:       }
69:       case 'read_file': {
70:         const start = args.startLine ?? 1;
71:         if (!Number.isInteger(start) || start < 1) throw new Error('Invalid startLine.');
72:         const lines = await textFile(args.path);
73:         if (start > lines.length) {
74:           return `[No lines read: ${args.path} has ${lines.length} lines, so startLine ${start} is past the end.]`;
75:         }
76:         // A partial read must say so; the first dogfood run stopped at line 200 of a 706-line
77:         // README because the previous note looked the same for complete and truncated reads.
78:         const delivered = [];
79:         let size = 0;
80:         for (const [index, line] of lines.slice(start - 1, start + 199).entries()) {
81:           const numbered = `${start + index}: ${line}`;
82:           const text = numbered.length > 20_000 ? `${numbered.slice(0, 20_000)} …[long line truncated]` : numbered;
83:           if (delivered.length && size + text.length + 1 > 20_000) break;
84:           delivered.push(text);
85:           size += text.length + 1;
86:         }
87:         const last = start + delivered.length - 1;
88:         const remaining = lines.length - last;
89:         return delivered.join('\n') + '\n' + (remaining > 0
90:           ? `[PARTIAL READ: lines ${start}-${last} of ${lines.length}. The remaining ${remaining} lines of ${args.path} have NOT been shown. Call read_file with path "${args.path}" and startLine ${last + 1} to read them.]`
91:           : `[Lines ${start}-${last} of ${lines.length}. End of ${args.path}; the whole file from line ${start} has been shown.]`);
92:       }
93:       case 'search': {
94:         if (typeof args.text !== 'string' || !args.text.trim()) throw new Error('Expected nonempty search text.');
95:         const matches = [];
96:         for (const path of files) {
97:           let lines;
98:           try { lines = await textFile(path); } catch { continue; }
99:           for (const [index, line] of lines.entries()) {
100:             if (line.toLowerCase().includes(args.text.toLowerCase())) {
101:               matches.push(`${path}:${index + 1}: ${line.slice(0, 300)}`);
102:               if (matches.length === 50) return matches.join('\n') + '\n[Stopped at 50 matches]';
103:             }
104:           }
105:         }
106:         return matches.join('\n') || 'No matches in readable tracked files.';
107:       }
108:       case 'history':
109:         if (args.path !== undefined && !known.has(args.path)) throw new Error('Choose a listed tracked file.');
110:         return (await git(['log', '-10', '--format=%h %s', '--', ...(args.path ? [args.path] : [])])).slice(0, 20_000);
111:       default:
112:         throw new Error(`Unknown repository tool: ${name}`);
113:     }
114:   };
115: }
